ON = ['b','d','g','h','k','kh','l','m','n','ng','p','q','r','s','sh','t','w','y','z','zh']
VO = ['a','e','i','o','u','ë']

def terms(s):
 return [re.sub(r'\s+',' ',x.strip().lower()) for x in s.split('|') if x.strip()]

def norm(s):
 return re.sub(r'[^a-z0-9 ]+','',s.casefold()).strip()

def loadcsv(p):
 with p.open('r',newline='',encoding='utf-8-sig') as f:return list(csv.DictReader(f))

def writecsv(p, rows):
 with p.open('w',newline='',encoding='utf-8') as f:
  w=csv.DictWriter(f,fieldnames=list(rows[0]));w.writeheader();w.writerows(rows)

def generate_word(concept,pos,occupied):
 for salt in range(10000):
  digest=hashlib.sha256((concept+'|'+pos+'|'+str(salt)).encode()).digest()
  # Use three or four syllables, avoiding artificial consonant clusters.
  parts=[]
  n=3 if digest[2]%3 else 4
  for i in range(n):parts.append(ON[digest[i*2] % len(ON)]+VO[digest[i*2+1] % len(VO)])
  result=''.join(parts)
  if result not in occupied:
   occupied.add(result)
   return result
 raise RuntimeError(concept)

def lookup_bases(words):
 match={}
 for w in words:
  if w['pos'] not in ('n','v','adj','adv'):continue
  candidates=[w['english'].split(';')[0].strip(),w['english']]
  for item in candidates:
   k=norm(item)
   if k and k not in match:match[k]=w
 return match

def main():
 words=loadcsv(ROOT/'data/lexicon.csv');original=list(words)
 occupied={w['qaroshi'] for w in words}
 old_glosses={(norm(w['english']),w['pos']) for w in words}
 # Do not invent duplicate headwords for an identical primary sense and POS.
 old_primaries={(norm(w['english'].split(';')[0]),w['pos']) for w in words}
 new=[];new_standalone=[];new_compounds=[];duplicates=collections.Counter()
 def add(form,pos,english,domain,type_,components='',note=''):
  english=english.strip();pr=(norm(english),pos)
  if pr in old_primaries or pr in old_glosses:
   duplicates['existing English sense']+=1;return None
  if form in occupied and type_=='compound':
   duplicates['compound spelling collision']+=1;return None
  if form not in occupied:occupied.add(form)
  else:
   duplicates['headword spelling collision']+=1;return None
  row={'id':f'Q5{len(new)+1:06d}','qaroshi':form,'pos':pos,'english':english,'domain':domain,'type':type_,'components':components,'note':note,
       'ipa':ipa_word(form),'reading':guide_word(form),'sound_out':sound_out_word(form)}
  words.append(row);new.append(row);old_primaries.add(pr)
  (new_compounds if type_=='compound' else new_standalone).append(row)
  return row
 # Domain-specific roots for contemporary use; no inflection padding.
 for domain,pos,tbl in BANK:
  for gloss in terms(tbl):
   if (norm(gloss),pos) in old_primaries:duplicates['preexisting term']+=1;continue
   form=generate_word(gloss,pos,occupied)
   # generate_word claims form; release it to the sole insertion check
   occupied.remove(form)
   add(form,pos,gloss,domain,'headword')
 # Transparent modifier-head compounds; use word meanings as documented.
 match=lookup_bases(words)
 missing=collections.Counter();attempted=0
 for domain,modifier_text,head_text in PRODUCTIVE:
  mods=terms(modifier_text);heads=terms(head_text)
  for m in mods:
   for h in heads:
    attempted+=1
    if m==h:continue
    left=match.get(norm(m));right=match.get(norm(h))
    if not left or not right:
     missing.update([m] if not left else []);missing.update([h] if not right else []);continue
    if left['qaroshi']==right['qaroshi']:continue
    # The English label is a compositional noun phrase, the right element is the head.
    english=m+' '+h
    combined=left['qaroshi']+right['qaroshi']
    if len(combined)>37:duplicates['overlong compound']+=1;continue
    add(combined,'n',english,domain,'compound',left['qaroshi']+' + '+right['qaroshi'],
        'Modifier–head compound: '+m+' modifies '+h+'.')
 # Stable sort; original records preserved without mutation, including identifiers.
 words.sort(key=lambda x:(x['qaroshi'],x['id']))
 writecsv(ROOT/'data/lexicon.csv',words)
 (ROOT/'data/lexicon.json').write_text(json.dumps(words,ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
 # English index: one row per canonical headword plus separately indexed semicolon glosses.
 cols=['english','qaroshi','pos','domain','ipa','reading','sound_out']
 index=[]
 for r in words:
  for en in r['english'].split(';'):
   if en.strip():index.append({k:r[k] if k!='english' else en.strip() for k in cols})
 index.sort(key=lambda x:(x['english'].casefold(),x['qaroshi']))
 writecsv(ROOT/'data/english_index.csv',index)
 # Build meaningful topical example sentences, using an established topic suffix.
 phrase=loadcsv(ROOT/'corpus/parallel_sentences.csv')
 noun_entries=[x for x in new if x['pos']=='n']
 verb_entries=[x for x in new_standalone if x['pos']=='v']
 # Domain-diverse selection (cycling) to avoid hundreds of consecutive examples from one field.
 groups=collections.defaultdict(list)
 for x in noun_entries:groups[x['domain']].append(x)
 selected=[]
 while groups and len(selected)<900:
  for domain in list(groups):
   if groups[domain]:selected.append(groups[domain].pop(0))
   if not groups[domain]:groups.pop(domain)
   if len(selected)>=900:break
 templates=[
   ('sen mi {q}-së shiri-te.','I spoke about {e}.','Topic-marked noun + completed speaking event'),
   ('hë ti {q}-së shiri-ki he?','Can you speak about {e}?','Topic marker + ability + question'),
   ('sen mi {q}-së shiri-yu.','I will speak about {e}.','Topic marker + future tense'),
   ('nëm naru {q}-së shiri-se.','We are talking about {e}.','Inclusive we + ongoing speech'),
   ('zha naru {q}-së shiri-yu!','We will talk about {e}!','Bright Trill + inclusive future'),
   ('sen sa {q}-së shiri-te hu.','They spoke about {e}, reportedly.','Reported evidential')
 ]
 for i,word in enumerate(selected):
  t,e,pattern=templates[i%len(templates)]
  q=t.format(q=word['qaroshi']);engl=e.format(e=word['english'])
  phrase.append({'id':f'S5{i+1:05d}','domain':word['domain'],'qaroshi':q,'english':engl,'note':'Topic noun: '+word['qaroshi']+'; '+pattern+'.','pattern':'Reference 5.0 topical corpus',
                 'ipa':ipa_text(q),'reading':guide_text(q),'sound_out':sound_out_text(q)})
 # Add a further 160 declarative sentences with new verb roots.
 for i,word in enumerate(verb_entries[:160]):
  # Action predicates can be intransitive; complements are supplied contextually.
  q=['sen mi '+word['qaroshi']+'-te.','dal naru '+word['qaroshi']+'-yu.','hë ti '+word['qaroshi']+'-ki he?',
     'sen sa '+word['qaroshi']+'-se.'][i%4]
  def english_inflect(phrase,kind):
   first,*rest=phrase.split(' ')
   past={'read':'read','send':'sent','write':'wrote','speak':'spoke','give':'gave','take':'took','make':'made','run':'ran','draw':'drew','fly':'flew','go':'went','come':'came','see':'saw','teach':'taught','lead':'led','keep':'kept','hold':'held','find':'found','buy':'bought','pay':'paid','build':'built','feel':'felt','seek':'sought','set':'set','put':'put','cut':'cut','break':'broke','choose':'chose','tell':'told','leave':'left','meet':'met'}
   if kind=='past':
    if first in past:head=past[first]
    elif first.endswith('e'):head=first+'d'
    elif first.endswith('y') and len(first)>1 and first[-2] not in 'aeiou':head=first[:-1]+'ied'
    else:head=first+'ed'
   else:
    if first.endswith('ie'):head=first[:-2]+'ying'
    elif first.endswith('e') and first not in ('see','be','agree'):head=first[:-1]+'ing'
    else:head=first+'ing'
   return ' '.join([head,*rest])
  en=['I '+english_inflect(word['english'],'past')+'.','We will '+word['english']+'.','Can you '+word['english']+'?',
      'They are '+english_inflect(word['english'],'ing')+'.'][i%4]
  phrase.append({'id':f'S5V{i+1:05d}','domain':word['domain'],'qaroshi':q,'english':en,'note':'Context supplies any omitted object for this action verb.','pattern':'Reference 5.0 verb morphology',
                 'ipa':ipa_text(q),'reading':guide_text(q),'sound_out':sound_out_text(q)})
 writecsv(ROOT/'corpus/parallel_sentences.csv',phrase)
 (ROOT/'corpus/parallel_sentences.json').write_text(json.dumps(phrase,ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
 stats=json.loads((ROOT/'data/statistics.json').read_text());stats.update({'standard':'Qaroshi Unified Standard 5.0','version':'5.0','dictionary_entries':len(words), 'english_index_rows':len(index),
  'sentences':len(phrase),'semantic_domains':len({x['domain'] for x in words}), 'parts_of_speech':dict(collections.Counter(x['pos'] for x in words)),
  'pronunciation_coverage':{'lexicon':len(words),'phrasebook':len(phrase),'supplementary':stats['pronunciation_coverage']['supplementary']},
  'sound_out_coverage':{'lexicon':len(words),'phrasebook':len(phrase)}})
 (ROOT/'data/statistics.json').write_text(json.dumps(stats,ensure_ascii=False,indent=2)+'\n')
 report={'original_entries':len(original),'new_standalone_entries':len(new_standalone),'new_compounds':len(new_compounds),'total_entries':len(words),
         'original_sentences':len(phrase)-1060,'new_sentences':1060,'total_sentences':len(phrase),'new_domains':len(set(x['domain'] for x in new)),
         'attempted_compounds':attempted,'skipped':dict(duplicates), 'missing_template_lemmas':missing.most_common(80)}
 (ROOT/'data/expansion_report.json').write_text(json.dumps(report,ensure_ascii=False,indent=2)+'\n')
 print(json.dumps(report,ensure_ascii=False,indent=2))

if __name__=='__main__':main()
